@startuml

class SensorController {
  + systemName : string
  + querySensorValues(sensorId : int) : float
  + configureSensor(sensorId : int, newRoomId : int) : void
  + updateSensorDescription(sensorId : int, newDesc : string) : void
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

class Inhabitant {
  + username : string
  + password : string
  + email : string
  + isAdmin : boolean
}

class Sensor {
  + vendorId : int
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class TemperatureSensor {}

class PowerSensor {
  + totalPowerConsumption : float
}

enum Unit {
  CELSIUS
  WATT
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {
  + checkThresholds() : void
  + sendAlert(email : string) : void
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor
Inhabitant "1..*" -- "1" Apartment
Inhabitant "1..*" -- "1" SensorController : logs_on
Sensor "1" -- "1" SensorValue : has_history
Sensor "1" -- "0..1" SensorValue : last_value
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
SensorController "1" -- "1" EMonitor : attached_to
EMonitor ..> Sensor : checks_thresholds
EMonitor ..> Inhabitant : sends_alert_to

